import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func getLsResult(dirPath string) string {
	if dirPath == "" {
		return ""
	}

	// Normalize the path to handle any redundant components
	normalizedPath, err := filepath.EvalSymlinks(dirPath)
	if err != nil {
		return ""
	}

	// Check if the path is absolute or relative
	absolutePath := normalizedPath
	if !filepath.IsAbs(absolutePath) {
		absolutePath = filepath.Join(os.Getwd(), absolutePath)
	}

	// Check if the path is within the current working directory to prevent directory traversal
	currentDir, _ := filepath.EvalSymlinks(os.Getwd())
	if !strings.HasPrefix(absolutePath, currentDir) {
		return ""
	}

	// Check if the directory exists and is a directory
	info, err := os.Stat(absolutePath)
	if err != nil {
		return ""
	}
	if !info.IsDir() {
		return ""
	}

	// Execute the ls -l command in the provided directory
	cmd := exec.Command("ls", "-l")
	cmd.Dir = absolutePath
	output, err := cmd.CombinedOutput()
	if err != nil {
		return ""
	}
	return string(output)
}
